html:
{#- ================================================================
    WORK ORDER COMPLETION — ATS SYNTHETIC (Pvt.) Ltd.
    Custom Print Format (Frappe / ERPNext, Jinja)
================================================================ -#}

{%- set prio  = doc.priority or "Normal" -%}
{%- set pkey  = prio | lower -%}
{%- set ctype = doc.complaint_type or "" -%}
{%- set wstat = doc.work_status or "Pending" -%}
{%- set state = "Cancelled" if doc.docstatus == 2 else (doc.workflow_state or ("Approved" if doc.docstatus == 1 else "Draft")) -%}
{%- set skey  = state | lower | replace(" ", "-") -%}

{%- set secs = frappe.utils.time_diff_in_seconds(
      (doc.completion_date ~ " " ~ (doc.completion_time or "00:00:00")),
      (doc.slip_date ~ " " ~ (doc.slip_time or "00:00:00"))
    ) if (doc.completion_date and doc.slip_date) else 0 -%}
{%- set mins = ((secs / 60) | int) if (secs and secs > 0) else 0 -%}
{%- set downtime = ("%02d:%02d:%02d" | format(mins // 1440, (mins % 1440) // 60, mins % 60)) if (secs and secs > 0) else "—" -%}

{%- macro person(u) -%}{{ ((frappe.db.get_value("User", u, "full_name") or u) | e) if u else "—" }}{%- endmacro -%}
{%- macro val(v) -%}{{ (v | e) if v else "—" }}{%- endmacro -%}

<style>
  .wo { font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif; color: #22282e; font-size: 11.5px; line-height: 1.45; position: relative; }
  .wo table { width: 100%; border-collapse: collapse; }
  .wo td { vertical-align: top; }

  /* Header */
  .wo .head { border-bottom: 3px solid #1c3a52; }
  .wo .head td { padding: 12px 4px 10px; vertical-align: middle; }
  .wo .logo-cell { text-align: left; }
  .wo .title-cell { text-align: right; }
  .wo .logo { height: 55px; width: auto; max-width: 100%; }
  .wo .title { font-size: 24px; font-weight: 800; letter-spacing: 3px; color: #1c3a52; line-height: 1; }
  .wo .title small { display: block; font-size: 10.5px; font-weight: 600; letter-spacing: .5px; color: #1f8a4c; margin-top: 6px; }

  /* Key info strip */
  .wo .strip td { border: 1px solid #c9d2db; border-top: 0; padding: 7px 10px; width: 25%; }
  .wo .lbl { font-size: 9.5px; color: #6b7785; display: block; margin-bottom: 0px; }
  .wo .val { font-size: 12.5px; font-weight: 600; color: #22282e; }
  .wo .ref { font-size: 15px; font-weight: 800; color: #1c3a52; }
  .wo .sub { font-size: 10.5px; color: #6b7785; font-weight: 600; }

  /* Pills */
  .wo .prio-row { margin: 12px 0 4px; }
  .wo .prio-row td { vertical-align: middle; }
  .wo .pill {
    display: inline-block; padding: 5px 14px; margin-right: 6px; border-radius: 20px;
    border: 1.5px solid #c9d2db; color: #9aa5b1; font-weight: 600; font-size: 11px;
    -webkit-print-color-adjust: exact; print-color-adjust: exact;
  }
  .wo .pill .box { display: inline-block; width: 9px; height: 9px; border: 1.5px solid currentColor; border-radius: 2px; margin-right: 6px; vertical-align: -1px; }
  .wo .pill.on.normal    { background: #e3f4e8; border-color: #1f8a4c; color: #1f8a4c; }
  .wo .pill.on.urgent    { background: #fff1d0; border-color: #c27c00; color: #a86b00; }
  .wo .pill.on.emergency { background: #fde3e1; border-color: #c62828; color: #c62828; }
  .wo .pill.on.new       { background: #e3eefb; border-color: #1f6fb2; color: #1f6fb2; }
  .wo .pill.on.repeated  { background: #fde3e1; border-color: #c62828; color: #c62828; }
  .wo .pill.on .box { background: currentColor; }

  /* Sections */
  .wo .sec { margin-top: 12px; border: 1px solid #c9d2db; page-break-inside: avoid; }
  .wo .sec-h {
    background: #eef2f6; border-bottom: 1px solid #c9d2db; padding: 6px 10px;
    font-size: 12px; font-weight: 700; color: #1c3a52; border-left: 4px solid #f2b705;
    -webkit-print-color-adjust: exact; print-color-adjust: exact;
  }
  .wo .sec-h.done { border-left-color: #1f8a4c; }
  .wo .grid td { padding: 8px 10px; border-right: 1px solid #e3e8ed; }
  .wo .grid td:last-child { border-right: 0; }
  .wo .grid tr + tr td { border-top: 1px solid #e3e8ed; }
  .wo .text {
    padding: 10px 12px; min-height: 60px; white-space: pre-wrap; font-size: 12px; line-height: 1.9;
    unicode-bidi: plaintext; text-align: start;
    font-family: "Segoe UI", Arial, "Noto Nastaliq Urdu", "Jameel Noori Nastaleeq", "Noto Naskh Arabic", sans-serif;
  }

  /* Parts table */
  .wo .parts th { background: #f6f8fa; color: #6b7785; font-size: 9.5px; font-weight: 600; text-align: left; padding: 6px 10px; border-bottom: 1px solid #c9d2db; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .wo .parts td { padding: 6px 10px; border-top: 1px solid #e3e8ed; }
  .wo .act { display: inline-block; padding: 1px 8px; border-radius: 3px; font-size: 10px; font-weight: 700; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .wo .act.repaired { background: #e3eefb; color: #1f6fb2; }
  .wo .act.replaced { background: #fff1d0; color: #a86b00; }

  /* Badges */
  .wo .badge { display: inline-block; padding: 3px 10px; border-radius: 3px; font-weight: 700; font-size: 11px; color: #fff; background: #6b7785; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .wo .badge.completed, .wo .badge.approved { background: #1f8a4c; }
  .wo .badge.pending, .wo .badge.pending-approval { background: #c27c00; }
  .wo .badge.rework-required, .wo .badge.cancelled { background: #c62828; }
  .wo .badge.draft { background: #6b7785; }
  .wo .big { font-size: 15px; font-weight: 800; color: #1c3a52; }

  .wo .line { border-bottom: 1px dotted #8a96a3; height: 16px; }

  /* Signatures */
  .wo .sign { margin-top: 50px; page-break-inside: avoid; }
  .wo .sign td { padding: 75px 12px 6px; text-align: center; width: 25%; }
  .wo .sign .sl { border-top: 1.5px solid #22282e; padding-top: 4px; font-size: 10.5px; font-weight: 600; color: #3d4752; }

  /* Tear-off counterfoil */
  .wo .cut { margin: 18px 0 8px; border-top: 1.5px dashed #8a96a3; position: relative; height: 0; }
  .wo .cut span { position: absolute; top: -9px; left: 12px; background: #fff; padding: 0 6px; font-size: 11px; color: #6b7785; }
  .wo .foil { border: 1.5px solid #1c3a52; page-break-inside: avoid; }
  .wo .foil-h { background: #1c3a52; color: #fff; padding: 5px 10px; font-weight: 700; font-size: 11px; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .wo .foil td { padding: 6px 10px; border-right: 1px solid #e3e8ed; vertical-align: middle; }

  /* Watermark until approved */
  .wo .wm {
    position: absolute; top: 340px; left: 0; width: 100%; text-align: center;
    font-size: 66px; font-weight: 900; letter-spacing: 6px; opacity: .07; color: #c27c00;
    -webkit-transform: rotate(-24deg); transform: rotate(-24deg); z-index: 0;
  }
  .wo .wm.rework-required, .wo .wm.cancelled { color: #c62828; }
  .wo .wm.draft { color: #6b7785; }

  .wo .foot { margin-top: 8px; font-size: 9px; color: #8a96a3; text-align: right; }
</style>

{%- set ats_logo = "data:image/png;base64," -%}

<div class="wo">

  {%- if state != "Approved" %}
  <div class="wm {{ skey }}">{{ state | upper }}</div>
  {%- endif %}

  <!-- Header -->
  <table class="head">
    <tr>
      <td class="logo-cell" style="width:58%;">
        <img class="logo" src="{{ ats_logo }}" alt="ATS Synthetic (Pvt.) Ltd.">
      </td>
      <td class="title-cell" style="width:42%;">
        <div class="title">WORK ORDER<small>Maintenance report</small></div>
      </td>
    </tr>
  </table>

  <!-- Key info strip -->
  <table class="strip">
    <tr>
      <td><span class="lbl">Completion no.</span><span class="ref">{{ doc.name }}</span></td>
      <td><span class="lbl">Work order no.</span><span class="ref">{{ doc.work_order_slip }}</span>{% if doc.reference_no %}<br><span class="sub">Ref: {{ doc.reference_no | e }}</span>{% endif %}</td>
      <td><span class="lbl">Fault date / time</span><span class="val">{{ doc.get_formatted("slip_date") or "—" }}</span><br><span class="sub">{{ doc.get_formatted("slip_time") or "" }}</span></td>
      <td><span class="lbl">Completion date / time</span><span class="val">{{ doc.get_formatted("completion_date") or "—" }}</span><br><span class="sub">{{ doc.get_formatted("completion_time") or "" }}</span></td>
    </tr>
  </table>

  <!-- Priority and complaint type -->
  <table class="prio-row">
    <tr>
      <td style="width:70px; font-weight:700; color:#1c3a52;">Priority</td>
      <td style="width:52%;">
        {%- for p in ["Normal", "Urgent", "Emergency"] %}
        <span class="pill {{ p | lower }} {{ 'on' if p | lower == pkey else '' }}"><span class="box"></span>{{ p }}</span>
        {%- endfor %}
      </td>
      <td style="width:105px; font-weight:700; color:#1c3a52;">Complaint type</td>
      <td>
        {%- for t in ["New", "Repeated"] %}
        <span class="pill {{ t | lower }} {{ 'on' if t == ctype else '' }}"><span class="box"></span>{{ t }}</span>
        {%- endfor %}
      </td>
    </tr>
  </table>

  <!-- Machine & departments -->
  <div class="sec">
    <div class="sec-h">Machine &amp; departments</div>
    <table class="grid">
      <tr>
        <td style="width:34%;"><span class="lbl">Requesting department</span><span class="val">{{ val(doc.requesting_department) }}</span></td>
        <td style="width:33%;"><span class="lbl">Work assigned to</span><span class="val">{{ val(doc.assigned_department) }}</span></td>
        <td style="width:33%;"><span class="lbl">Shift</span><span class="val">{{ val(doc.shift) }}</span></td>
      </tr>
      <tr>
        <td><span class="lbl">Asset</span><span class="val">{{ val(doc.asset) }}</span></td>
        <td colspan="2"><span class="lbl">Machine name</span><span class="val">{{ val(doc.machine_name) }}</span></td>
      </tr>
    </table>
  </div>

  <!-- Reported defect -->
  <div class="sec">
    <div class="sec-h">Reported defect</div>
    <div class="text">{{ doc.defect_description | e if doc.defect_description else "" }}</div>
  </div>

  <!-- Work done -->
  <div class="sec">
    <div class="sec-h done">Work done / repair details</div>
    <div class="text">{{ doc.details_of_defects | e if doc.details_of_defects else "" }}</div>
  </div>

  <!-- Parts -->
  {%- if doc.parts %}
  <div class="sec">
    <div class="sec-h done">Parts repaired / replaced</div>
    <table class="parts">
      <tr>
        <th style="width:6%;">#</th>
        <th style="width:42%;">Part name</th>
        <th style="width:16%;">Action</th>
        <th style="width:10%;">Qty</th>
        <th>Remarks</th>
      </tr>
      {%- for p in doc.parts %}
      <tr>
        <td>{{ loop.index }}</td>
        <td><span class="val">{{ val(p.part_name) }}</span></td>
        <td><span class="act {{ (p.action or '') | lower }}">{{ val(p.action) }}</span></td>
        <td>{{ p.get_formatted("qty") }}</td>
        <td>{{ val(p.remarks) }}</td>
      </tr>
      {%- endfor %}
    </table>
  </div>
  {%- endif %}

  <!-- Completion summary -->
  <div class="sec">
    <div class="sec-h done">Completion summary</div>
    <table class="grid">
      <tr>
        <td style="width:34%;"><span class="lbl">Downtime (DD:HH:MM)</span><span class="big">{{ downtime }}</span></td>
        <td style="width:33%;"><span class="lbl">Work status</span><span class="badge {{ wstat | lower }}">{{ wstat }}</span></td>
        <td style="width:33%;"><span class="lbl">Completed by / incharge</span><span class="val">{{ person(doc.completed_by) }}</span></td>
      </tr>
      <tr>
        <td colspan="3"><span class="lbl">Machine received back by (requesting dept.)</span><span class="val">{{ person(doc.received_by) }}</span></td>
      </tr>
    </table>
    {%- if doc.remarks %}
    <div class="text" style="border-top:1px solid #e3e8ed; min-height:0;"><span class="lbl">Remarks</span>{{ doc.remarks | e }}</div>
    {%- endif %}
  </div>

  <!-- Approval -->
  <div class="sec">
    <div class="sec-h">Approval</div>
    <table class="grid">
      <tr>
        <td style="width:34%;"><span class="lbl">Approval status</span><span class="badge {{ skey }}">{{ state }}</span></td>
        <td style="width:33%;"><span class="lbl">Approved by</span><span class="val">{{ person(doc.approved_by) }}</span></td>
        <td style="width:33%;"><span class="lbl">Approved on</span><span class="val">{{ doc.get_formatted("approved_on") or "—" }}</span></td>
      </tr>
    </table>
    {%- if doc.approver_remarks %}
    <div class="text" style="border-top:1px solid #e3e8ed; min-height:0;"><span class="lbl">Approver remarks</span>{{ doc.approver_remarks | e }}</div>
    {%- endif %}
  </div>

  <!-- Signatures -->
  <table class="sign">
    <tr>
      <td><div class="sl">Completed by</div></td>
      <td><div class="sl">Machine received by</div></td>
      <td><div class="sl">Department head</div></td>
      <td><div class="sl">Approved by</div></td>
    </tr>
  </table>

  <!-- Tear-off counterfoil -->
  <div class="cut"><span>&#9986; Cut here — machine handover receipt for the requesting department</span></div>

  <div class="foil">
    <div class="foil-h">Machine handover receipt &nbsp;|&nbsp; {{ doc.name }} &nbsp;|&nbsp; {{ doc.work_order_slip }}</div>
    <table>
      <tr>
        <td style="width:22%;"><span class="lbl">Completed on</span><span class="val">{{ doc.get_formatted("completion_date") or "—" }}</span></td>
        <td style="width:24%;"><span class="lbl">Machine</span><span class="val">{{ val(doc.machine_name or doc.asset) }}</span></td>
        <td style="width:14%;"><span class="lbl">Downtime</span><span class="val">{{ downtime }}</span></td>
        <td style="width:20%;"><span class="lbl">Repaired by</span><span class="val">{{ val(doc.assigned_department) }}</span></td>
        <td style="width:20%; border-right:0;"><span class="lbl">Received by (sign)</span><div class="line" style="margin-top:6px;"></div></td>
      </tr>
    </table>
  </div>

  <div class="foot">Printed on {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "dd-MM-yyyy HH:mm") }}</div>
</div>
